+  } else if (v == 36000) {
+    g_snprintf(s, ITEM_LABEL_LENGTH, "moreThanHour(%d)", v);
+  } else {
+    g_snprintf(s, ITEM_LABEL_LENGTH, "%02u:%02u.%u (%d)",
